groups={'BAGE_':5,'BOLUS_RENDER_':3,'BWP_':4,'CAGE_':5,'DBSIZE_':5,'ERRORCODES_':3,'IAGE_':4,'OPENAPS_':11,'PUMP_':12,'SAGE_':4,'TREATMENTNOTIFY_':2,'UPBAT_':3,'XDRIPJS_':3}
union=set(open('union.txt').read().split())
# expand groups from the union
exp=[]
for p,n in groups.items():
    got=sorted(x for x in union if x.startswith(p))
    exp+=got
    if len(got)!=n: print("GROUP MISMATCH",p,"doc says",n,"union has",len(got),got)
T=set(T_site+T_alarm+T_feat+T_frames+T_conn+plug_expl+exp)
print("T size:",len(T),"(doc says 160)")
allc=T|set(TS)|set(D_listen+D_store+D_ten+D_proc)|set(B)|set(X)
print("classes T+TS+D+B+X (no AWS):",len(allc),"(doc says 245)")
allc2=allc|set(D_aws)|set(B6)
print("plus AWS + B6:",len(allc2))
print()
print("IN UNION, NOT CLASSIFIED ANYWHERE:")
for n in sorted(union-allc2): print("  ",n)
print()
print("CLASSIFIED BUT NOT IN UNION:")
for n in sorted(allc2-union): print("  ",n)
